def f(x,k): return SBOX[(x ^ k) & 0xff]
def encrypt_block(P, k0, k1):
    L=(P>>8)&0xff; R=P&0xff
    L1,R1 = R,   L ^ f(R,k0)
    L2,R2 = R1,  L1 ^ f(R1,k1)
    return (L2<<8)|R2
def decrypt_block(C, k0, k1):
    L2c=(C>>8)&0xff; R2c=C&0xff
    R1 = L2c
    R0 = R2c ^ f(R1,k1)
    L0 = R1 ^ f(R0,k0)
    return (L0<<8)|R0
